-- Crystal Caverns V1: a server-authoritative expedition destination.

create table public.crystal_cavern_runs(
  id bigint generated always as identity primary key,
  player_id uuid not null references public.players(id) on delete cascade,
  status text not null default 'awaiting_funding',depth integer not null default 0,overdepth integer not null default 0,
  progress integer not null default 0,target integer not null default 0,danger integer not null default 0,
  instability integer not null default 0,total_funding numeric not null default 0,
  secured_cargo jsonb not null default '[]',unsecured_cargo jsonb not null default '[]',
  secured_artifacts jsonb not null default '[]',unsecured_artifacts jsonb not null default '[]',
  pending jsonb,incident_log jsonb not null default '[]',extraction_reason text,settlement jsonb,
  started_at timestamptz not null default now(),updated_at timestamptz not null default now(),settled_at timestamptz,
  constraint crystal_status check(status in('awaiting_funding','active','decision','ready_to_extract','forced_extraction','extracted','settled')),
  constraint crystal_depth check(depth between 0 and 10),constraint crystal_instability check(instability>=0)
);
create unique index crystal_one_open_run on public.crystal_cavern_runs(player_id) where status<>'settled';
alter table public.crystal_cavern_runs enable row level security;
revoke all on public.crystal_cavern_runs from public,anon,authenticated;grant all on public.crystal_cavern_runs to service_role;

create table public.crystal_cavern_artifacts(
  key text primary key,name text not null,collection text not null,min_depth integer not null default 1,min_overdepth integer not null default 0,
  min_instability integer not null default 0,pool text not null,weight numeric not null default 1,duplicate_value numeric not null,
  passive_name text not null,passive_description text not null,sort_order integer not null unique
);
